// Flatten the Open States response and keep the fields we need.
const items = $input.first().json.results || [];
return items.map(b => ({
  json: {
    id: b.id,
    state: (b.jurisdiction?.name || '').toLowerCase().slice(0, 2),
    session: b.session,
    identifier: b.identifier,
    title: (b.title || '').slice(0, 500),
    latest_action_date: b.latest_action_date,
    latest_action: b.latest_action_description,
    subjects: b.subjects || [],
    url: b.openstates_url,
  }
}));

// Merge Claude's classification onto the bill record.
const bill = $('Loop Over Bills').item.json;
const resp = $input.first().json;
const text = resp?.content?.[0]?.text || '{}';
let classification;
try { classification = JSON.parse(text); } catch (e) { classification = null; }
return [{ json: { ...bill, classification } }];

// Combine the two HTTP responses into one record for downstream nodes.
const accounts = $('Fetch Accounts (raw GitHub)').first().json;
const yamlText = $('Fetch Scoring Config (raw GitHub)').first().json.data || $('Fetch Scoring Config (raw GitHub)').first().json;
// minimal YAML parse via JSON conversion would need a library; in n8n use the YAML node or pre-convert.
// For demo simplicity, the scoring config is also published as JSON at the same path with .json extension.
const yaml = require('js-yaml');
const cfg = typeof yamlText === 'string' ? yaml.load(yamlText) : yamlText;
return [{ json: { accounts, cfg } }];

// For each bill, score against every account that gates pass: industry overlap (direct or adjacent) AND state in footprint.
const ENGAGEMENT = { 'prospect-hot': 1.0, 'customer-renewal': 0.9, 'prospect-warm': 0.7, 'customer-active': 0.6, 'prospect-cold': 0.4, 'churned-recent': 0.2 };
const ADJACENT = { insurance: ['financial_services','healthcare'], financial_services: ['insurance'], healthcare: ['insurance'], retail: ['food_service'], energy: ['manufacturing'], telecom: ['tech'] };

const bill = $('Merge Classification').item.json;
const { accounts, cfg } = $('Combine Accounts + Config').item.json;
const cls = bill.classification;
if (!cls?.industries?.length) return [];
const industries = new Set(cls.industries);

const out = [];
for (const a of accounts) {
  const direct = industries.has(a.industry);
  const adj = (ADJACENT[a.industry] || []).some(i => industries.has(i));
  if (!direct && !adj) continue;
  if (!a.state_footprint.includes(bill.state)) continue;
  const v = cfg.verticals[a.vertical_config];
  if (!v) continue;
  const w = v.weights;
  const breakdown = {
    industry_match: (direct ? 1.0 : 0.4) * w.industry_match,
    urgency: ((cls.urgency || 1) / 5) * w.urgency,
    state_footprint_overlap: 1.0 * w.state_footprint_overlap,
    engagement: (ENGAGEMENT[a.engagement_status] || 0.4) * w.engagement,
  };
  const score = +(breakdown.industry_match + breakdown.urgency + breakdown.state_footprint_overlap + breakdown.engagement).toFixed(4);
  if (score >= 0.6 && (cls.urgency || 0) >= v.urgency_floor) {
    out.push({ json: { bill, account: a, score, breakdown } });
  }
}
return out;

