// Append to outputs/hubspot_tasks.json. In real deploy, swap for HubSpot CRM API.
const fs = require('fs');
const path = require('path');
const REPO = $env.PIPELINE_REPO_PATH || '/data/policy-signal-engine';
const file = path.join(REPO, 'outputs/hubspot_tasks.json');
const existing = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file)) : [];
const m = $('Router').item.json;
const draft = $input.first().json?.content?.[0]?.text || '';
const task = {
  task_id: 'task_' + m.bill.identifier.replace(/\s+/g,'') + '_' + m.account.id,
  owner_ae: m.account.owner_ae,
  account_id: m.account.id,
  account_name: m.account.name,
  subject: '[Policy Signal] ' + m.bill.identifier + ' (' + m.bill.state.toUpperCase() + ') — ' + m.account.name,
  body: draft,
  due_in_days: 2,
  score: m.score,
  drafted_by: 'claude-opus-4-7',
  created_at: new Date().toISOString(),
};
fs.writeFileSync(file, JSON.stringify([...existing, task], null, 2));
return [{ json: task }];

// Append to outputs/sequences.json.
const fs = require('fs');
const path = require('path');
const REPO = $env.PIPELINE_REPO_PATH || '/data/policy-signal-engine';
const file = path.join(REPO, 'outputs/sequences.json');
const existing = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file)) : [];
const m = $('Router').item.json;
const draft = $input.first().json?.content?.[0]?.text || '';
const step = {
  sequence_id: 'seq_' + m.account.vertical_config + '_weekly',
  step: 'policy_signal_touch',
  account_id: m.account.id,
  account_name: m.account.name,
  owner_ae: m.account.owner_ae,
  subject_line: m.bill.identifier + ' just moved in ' + m.bill.state.toUpperCase() + ' — relevant to ' + m.account.name + '?',
  body: draft,
  score: m.score,
  drafted_by: 'claude-sonnet-4-6',
  queued_at: new Date().toISOString(),
};
fs.writeFileSync(file, JSON.stringify([...existing, step], null, 2));
return [{ json: step }];

// Append to data/outcomes.json. One row per routed pair, outcome null until later enrichment.
const fs = require('fs');
const path = require('path');
const REPO = $env.PIPELINE_REPO_PATH || '/data/policy-signal-engine';
const file = path.join(REPO, 'data/outcomes.json');
const existing = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file)) : [];
const m = $('Router').item.json;
const urgency = m.bill.classification.urgency;
const action = urgency === 5 ? 'slack_alert' : (m.score >= 0.8 && m.account.tier <= 2 ? 'hubspot_task' : 'sequence_enroll');
const entry = {
  timestamp: new Date().toISOString(),
  bill_id: m.bill.id,
  bill_identifier: m.bill.identifier,
  account_id: m.account.id,
  score: m.score,
  action_taken: action,
  outcome: null,
  outcome_logged_at: null,
};
fs.writeFileSync(file, JSON.stringify([...existing, entry], null, 2));
return [{ json: entry }];
